from taf.cloud.cbam.schemas.schema_base import CbamSchema
from taf.cloud.cbam.schemas.v3.operation_execution import OperationExecution


class VnfInfoLinks(CbamSchema):
    def __init__(self, self_link, operation_executions=None, extensions=None, vnf_configurable_properties=None,
                 instantiated_vnf_info=None, modify_info=None, heal=None, scale=None, terminate=None, list_link=None,
                 delete=None, instantiate=None):
        self.self_link = self_link
        self.operation_executions = operation_executions
        self.extensions = extensions
        self.vnf_configurable_properties = vnf_configurable_properties
        self.instantiated_vnf_info = instantiated_vnf_info
        self.modify_info = modify_info
        self.heal = heal
        self.scale = scale
        self.terminate = terminate
        self.list_link = list_link
        self.delete = delete
        self.instantiate = instantiate

    @classmethod
    def from_response_dict(cls, response_dict):
        def get_href_attribute(response, key):
            return response[key]['href'] if key in response else None

        self_link = response_dict['self']['href']
        operation_executions = get_href_attribute(response_dict, 'operationExecutions')
        extensions = get_href_attribute(response_dict, 'extensions')
        vnf_configurable_properties = get_href_attribute(response_dict, 'vnfConfigurableProperties')
        instantiated_vnf_info = get_href_attribute(response_dict, 'instantiatedVnfInfo')
        modify_info = get_href_attribute(response_dict, 'modifyInfo')
        heal = get_href_attribute(response_dict, 'heal')
        scale = get_href_attribute(response_dict, 'scale')
        terminate = get_href_attribute(response_dict, 'terminate')
        list_link = get_href_attribute(response_dict, 'list')
        delete = get_href_attribute(response_dict, 'delete')
        instantiate = get_href_attribute(response_dict, 'instantiate')

        return cls(self_link=self_link, operation_executions=operation_executions, extensions=extensions,
                   vnf_configurable_properties=vnf_configurable_properties, instantiated_vnf_info=instantiated_vnf_info,
                   modify_info=modify_info, heal=heal, scale=scale, terminate=terminate, list_link=list_link,
                   delete=delete, instantiate=instantiate)

    def as_dict(self):
        def get_links_dict(attr):
            d = {}
            for key, value in attr.items():
                if value:
                    d[key] = {'href': value}
            return d

        attributes = {'operationExecutions': self.operation_executions, 'extensions': self.extensions,
                      'vnfConfigurableProperties': self.vnf_configurable_properties,
                      'instantiatedVnfInfo': self.instantiated_vnf_info, 'modifyInfo': self.modify_info,
                      'heal': self.heal, 'scale': self.scale, 'terminate': self.terminate, 'list': self.list_link,
                      'delete': self.delete, 'instantiate': self.instantiate}

        result = get_links_dict(attributes)
        result['self'] = {'href': self.self_link}
        return result


class VnfInfo(CbamSchema):
    def __init__(self, id=None, vnfd_id=None, vnf_software_version=None,
                 vnfd_version=None, on_boarded_vnf_pkg_info_id=None, instantiation_state=None,
                 name=None, description=None, vnf_provider=None, vnf_product_name=None, operation_executions=None,
                 instantiated_vnf_info=None, vnf_configurable_properties=None, extensions=None, metadata=None,
                 links=None):
        self.id = id
        self.vnfd_id = vnfd_id
        self.vnf_software_version = vnf_software_version
        self.vnfd_version = vnfd_version
        self.on_boarded_vnf_pkg_info_id = on_boarded_vnf_pkg_info_id
        self.instantiation_state = instantiation_state
        self.name = name
        self.description = description
        self.vnf_provider = vnf_provider
        self.vnf_product_name = vnf_product_name
        self.operation_executions = operation_executions
        self.instantiated_vnf_info = instantiated_vnf_info
        self.vnf_configurable_properties = vnf_configurable_properties
        self.extensions = extensions
        self.metadata = metadata
        self.links = links

    @classmethod
    def from_response_dict(cls, response_dict):
        links = None

        operation_executions = None
        if '_links' in response_dict:
            links = VnfInfoLinks.from_response_dict(response_dict['_links'])
        if 'operationExecutions' in response_dict:
            operation_executions = [OperationExecution.from_response_dict(execution)
                                    for execution in response_dict['operationExecutions']]

        return cls(
            id=response_dict['id'],
            vnfd_id=response_dict['vnfdId'],
            vnf_software_version=response_dict['vnfSoftwareVersion'],
            vnfd_version=response_dict['vnfdVersion'],
            on_boarded_vnf_pkg_info_id=response_dict['onboardedVnfPkgInfoId'],
            instantiation_state=response_dict['instantiationState'],
            name=response_dict.get('name', None),
            description=response_dict.get('description', None),
            vnf_provider=response_dict.get('vnfProvider', None),
            vnf_product_name=response_dict.get('vnfProductName', None),
            operation_executions=operation_executions,
            instantiated_vnf_info=response_dict.get('instantiatedVnfInfo', None),
            vnf_configurable_properties=response_dict.get('vnfConfigurableProperties', None),
            extensions=response_dict.get('extensions', None),
            metadata=response_dict.get('metadata', None),
            links=links)

    def as_dict(self):
        def get_vnf_info_dict(d, attr):
            for key, value in attr.items():
                if value:
                    d[key] = value
            return d

        result = {'id': self.id,
                  'vnfdId': self.vnfd_id,
                  'vnfSoftwareVersion': self.vnf_software_version,
                  'vnfdVersion': self.vnfd_version,
                  'onboardedVnfPkgInfoId': self.on_boarded_vnf_pkg_info_id,
                  'instantiationState': self.instantiation_state}

        oes = None
        if self.operation_executions is not None:
            oes = [oe.as_dict() for oe in self.operation_executions]

        if self.links is not None:
            links = self.links.as_dict()
        else:
            links = None

        attributes = {'name': self.name, 'description': self.description,
                      'vnfProvider': self.vnf_provider,
                      'vnfProductName': self.vnf_product_name,
                      'operationExecutions': oes,
                      'instantiatedVnfInfo': self.instantiated_vnf_info,
                      'vnfConfigurableProperties': self.vnf_configurable_properties,
                      'extensions': self.extensions,
                      'metadata': self.metadata,
                      '_links': links}
        result = get_vnf_info_dict(result, attributes)

        return result
